fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // All vectors must have the same length as per the problem statement
    let len = dst.len();
    assert_eq!(src.len(), len);
    assert_eq!(mask.len(), len);
    
    let mut result = Vec::with_capacity(len);
    
    for i in 0..len {
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }
    
    result
}